                input[2] = [] // pon
                input[3] = [] // pon index
                input[4] = BCFTOOLS_REHEADER.out.vcf.map { meta, vcf -> vcf }
                // index staged under a different name, the module must place it at <germline_resource>.tbi
                input[5] = BCFTOOLS_REHEADER.out.index.map { meta, tbi -> tbi.copyTo(tbi.resolveSibling('gnomad.tbi')) }
                input[6] = [] // alleles
                input[7] = [] // alleles index
                """
            }
        }

        then {
