                { assert variants.any { variant -> variant.getAttributeAsDoubleList("POPAF", 6.0).any { popaf -> popaf < 6.0 } } },
                { assert snapshot(sanitizeOutput(process.out, variantsMD5Keys: ["vcf"], unstableKeys: ["tbi", "f1r2"])).match() }
            )
        }

